import type { IncomingMessage, ServerResponse } from 'node:http';

// Vercel entry. Fastify's auto-detected entry (src/server.ts) fails at runtime on Vercel,
// so we use the classic `api/` handler and forward requests to the Fastify server instance.
// `../dist/vercel.js` is generated by tsup during the build.
export default async function handler(req: IncomingMessage, res: ServerResponse) {
  try {
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore -- generated by tsup at build time; may not exist when type-checking
    const { default: app } = await import('../dist/vercel.js');
    await app.ready();
    app.server.emit('request', req, res);
  } catch (err) {
    res.statusCode = 500;
    res.setHeader('content-type', 'text/plain');
    res.end(err instanceof Error ? `${err.name}: ${err.message}` : String(err));
  }
}
